package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFChart;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTChart;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTPlotArea;
import org.openxmlformats.schemas.drawingml.x2006.chart.CTOfPieChart;
import org.apache.poi.xddf.usermodel.chart.XDDFChartData;
import java.util.List;
import java.util.LinkedList;

public class ChartUtilsgetChartSeries_CTPlotAreagetOfPieChartArrayFikaTest {

    @Test
    public void testGetChartSeriesInvokesGetOfPieChartArray() throws Exception {
        // Create mock chart
        XWPFChart chart = Mockito.mock(XWPFChart.class);

        // Create mock CTChart and CTPlotArea
        CTChart ctChart = Mockito.mock(CTChart.class);
        CTPlotArea plotArea = Mockito.mock(CTPlotArea.class);

        // Setup mock chain
        Mockito.when(chart.getCTChart()).thenReturn(ctChart);
        Mockito.when(ctChart.getPlotArea()).thenReturn(plotArea);

        // Setup empty chart series list
        List<XDDFChartData> emptySeries = new LinkedList<>();
        Mockito.when(chart.getChartSeries()).thenReturn(emptySeries);

        // Setup plotArea to have one ofPieChart
        Mockito.when(plotArea.sizeOfOfPieChartArray()).thenReturn(1);

        // Create mock CTOfPieChart for the array element
        CTOfPieChart ofPieChart = Mockito.mock(CTOfPieChart.class);
        Mockito.when(plotArea.getOfPieChartArray(0)).thenReturn(ofPieChart);

        // Execute the entry point method
        ChartUtils.getChartSeries(chart);

        // The test will invoke plotArea.getOfPieChartArray(0) during execution
        // No assertions needed per requirements
    }
}

