        XmlObject o = cursor.getObject();
        if (o instanceof CTP) {
            XWPFParagraph p = new XWPFParagraph(((CTP) (o)), this);
            paragraphs.add(p);
            bodyElements.add(p);
        }
        if (o instanceof CTSdtBlock) {
            XWPFSDT c = new XWPFSDT(((CTSdtBlock) (o)), this);
            bodyElements.add(c);
        }
