 */
public void removeParagraph(int pos) {
    XWPFParagraph removedParagraph = paragraphs.get(pos);
    paragraphs.remove(pos);
    ctTxbxContent.removeP(pos);
    bodyElements.remove(removedParagraph);
}

/**
