package com.deepoove.poi.util;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.apache.poi.xwpf.usermodel.XWPFTableRow;
import org.junit.jupiter.api.Test;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTbl;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblGrid;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblGridCol;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblPr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblWidth;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STTblWidth;

public class TableToolswidthTable_CTTblGridColsetWFikaTest {

    @Test
    public void testWidthTableCallsCTTblGridColSetW() throws Exception {
        XWPFTable table = mock(XWPFTable.class);

        CTTbl ctTbl = mock(CTTbl.class);
        when(table.getCTTbl()).thenReturn(ctTbl);

        CTTblPr ctTblPr = mock(CTTblPr.class);
        when(ctTbl.getTblPr()).thenReturn(ctTblPr);

        CTTblWidth ctTblWidth = mock(CTTblWidth.class);
        when(ctTblPr.isSetTblW()).thenReturn(true);
        when(ctTblPr.getTblW()).thenReturn(ctTblWidth);

        when(ctTblPr.addNewTblW()).thenReturn(ctTblWidth);

        CTTblGrid ctTblGrid = mock(CTTblGrid.class);
        when(ctTbl.getTblGrid()).thenReturn(ctTblGrid);
        when(ctTbl.isSetTblGrid()).thenReturn(true);

        List<CTTblGridCol> gridCols = new ArrayList<>();
        CTTblGridCol gridCol1 = mock(CTTblGridCol.class);
        CTTblGridCol gridCol2 = mock(CTTblGridCol.class);
        gridCols.add(gridCol1);
        gridCols.add(gridCol2);

        when(ctTblGrid.addNewGridCol()).thenReturn(gridCol1, gridCol2);

        XWPFTableRow row = mock(XWPFTableRow.class);
        List<XWPFTableRow> rows = new ArrayList<>();
        rows.add(row);
        when(table.getRows()).thenReturn(rows);

        float[] colWidths = new float[] { 5.0f, 10.0f };
        TableTools.widthTable(table, colWidths);
    }
}

