            runs.add(run);
            sdtElements.add(run);
        } else if (o instanceof CTSdtRun) {
            XWPFStructuredDocumentTag c = new XWPFStructuredDocumentTag(((CTSdtRun) (o)), this);
            sdtElements.add(c);
        }
    } 
    cursor.dispose();
}

