package com.deepoove.poi.policy;

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.apache.poi.xwpf.usermodel.BreakType;
import com.deepoove.poi.data.TextRenderData;
import com.deepoove.poi.data.HyperlinkTextRenderData;
import com.deepoove.poi.util.TableTools;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import java.lang.reflect.Field;

public class HelperrenderTextRun_XWPFRunaddBreakFikaTest {

    @Test
    public void testRenderTextRunInvokesAddBreak() throws Exception {
        // Create real XWPFDocument and XWPFRun
        XWPFDocument document = new XWPFDocument();
        XWPFRun run = document.createParagraph().createRun();

        // Create TextRenderData with text containing line breaks
        TextRenderData data = new TextRenderData("First line\nSecond line\nThird line");

        // Set up TableTools.isInsideTable to return true using reflection
        // This is necessary to trigger the addBreak path
        Field field = TableTools.class.getDeclaredField("INSIDE_TABLE");
        field.setAccessible(true);
        field.set(null, true);

        // Call the entry point method
        TextRenderPolicy.Helper.renderTextRun(run, data);

        // Reset the static field
        field.set(null, false);
    }
}

