import java.util.Arrays;
import java.util.List;

public class MultiSeriesChartTemplateRenderPolicydoRender_XDDFNumericalDataSourcesetFormatCodeFikaTest {

    @Test
    public void testDoRender() throws Exception {
        // Create the policy instance
        MultiSeriesChartTemplateRenderPolicy policy = new MultiSeriesChartTemplateRenderPolicy();

        // Mock ChartTemplate
        ChartTemplate chartTemplate = Mockito.mock(ChartTemplate.class);
        XWPFChart chart = Mockito.mock(XWPFChart.class);
        Mockito.when(chartTemplate.getChart()).thenReturn(chart);

        // Mock chart series
        List<XDDFChartData> chartSeries = new ArrayList<>();
        XDDFChartData chartData = Mockito.mock(XDDFChartData.class);
        chartSeries.add(chartData);
        Mockito.when(chart.getChartSeries()).thenReturn(chartSeries);

        // Mock series count and individual series
        Mockito.when(chartData.getSeriesCount()).thenReturn(1);
        XDDFChartData.Series series = Mockito.mock(XDDFChartData.Series.class);
        Mockito.when(chartData.getSeries(0)).thenReturn(series);

        // Mock numerical data source with format code
        XDDFNumericalDataSource<?> valuesData = Mockito.mock(XDDFNumericalDataSource.class);
        Mockito.when(series.getValuesData()).thenReturn(valuesData);
        Mockito.when(valuesData.getFormatCode()).thenReturn("General");

        // Mock template
        XWPFTemplate template = Mockito.mock(XWPFTemplate.class);

        // Create test data
        String[] categories = new String[]{"Cat1", "Cat2"};
        List<SeriesRenderData> seriesDatas = Arrays.asList(
            new SeriesRenderData("Series1", new Double[]{1.0, 2.0})
        );
        ChartMultiSeriesRenderData data = new ChartMultiSeriesRenderData();
        data.setCategories(categories);
        data.setSeriesDatas(seriesDatas);

        // Mock workbook and sheet
        XSSFSheet sheet = Mockito.mock(XSSFSheet.class);
        Mockito.when(chart.getWorkbook()).thenReturn(Mockito.mock(org.apache.poi.xssf.usermodel.XSSFWorkbook.class));
        Mockito.when(chart.getWorkbook().getSheetAt(0)).thenReturn(sheet);

        // Execute the entry point method
        policy.doRender(chartTemplate, data, template);
    }
}

