        @SuppressWarnings("unchecked")
        HashMap<BigInteger, XWPFAbstractNum> abstractNumMap = 
            (HashMap<BigInteger, XWPFAbstractNum>) abstractNumMapField.get(numbering);
        abstractNumMap.put(abstractNumId, abstractNum);

        // Execute the entry point method
        numberingContinue.updateNumbering(sourceParagraph, targetParagraph);
    }
}

