        XWPFParagraph source = mock(XWPFParagraph.class);
        XWPFParagraph target = mock(XWPFParagraph.class);

        // Setup document and numbering
        when(source.getDocument()).thenReturn(document);
        when(document.getNumbering()).thenReturn(numbering);

        // Setup numID
        BigInteger numID = BigInteger.valueOf(1);
        when(source.getNumID()).thenReturn(numID);

        // Setup XWPFNum
        XWPFNum num = mock(XWPFNum.class);
        CTNum ctNum = CTNum.Factory.newInstance();
        ctNum.setAbstractNumId(CTNum.Factory.newInstance().getAbstractNumId());
        when(num.getCTNum()).thenReturn(ctNum);
        when(numbering.getNum(numID)).thenReturn(num);

