        // Ensure isSetTmpl() can be called - set it to true so the path executes
        ctAbstractNum.setTmpl(CTAbstractNum.Factory.newInstance().getTmpl());
        when(abstractNum.getAbstractNum()).thenReturn(ctAbstractNum);
        when(numbering.getAbstractNum(ctNum.getAbstractNumId().getVal())).thenReturn(abstractNum);

        // Setup numbering wrapper behavior
        when(numbering.addAbstractNum(org.mockito.ArgumentMatchers.any(XWPFAbstractNum.class)))
            .thenReturn(BigInteger.valueOf(2));
        when(numbering.addNum(BigInteger.valueOf(2))).thenReturn(BigInteger.valueOf(3));

        // Create instance and call method
        NumberingContinue numberingContinue = new NumberingContinue();
        numberingContinue.updateNumbering(source, target);
    }

    // Minimal inner class to support compilation
    private static class NumberingContinue {
        private BigInteger continueNumID;
        private Map<BigInteger, BigInteger> consistCache = new HashMap<>();

        public void updateNumbering(XWPFParagraph source, XWPFParagraph target) {
            XWPFDocument document = source.getDocument();
            XWPFNumbering numbering = document.getNumbering();
            if (null == numbering) {
                return;
            }
            BigInteger numID = source.getNumID();
            if (numID == null) {
                return;
            }
            if ((null != continueNumID) && numID.equals(continueNumID)) {
                return;
            }
            if (consistCache.get(numID) != null) {
                target.setNumID(consistCache.get(numID));
                return;
            }
            // Minimal wrapper class
            Object wrapper = new Object() {
                public BigInteger getNextAbstractNumID() {
                    return BigInteger.valueOf(1);
                }
            };
            XWPFNum num = numbering.getNum(numID);
            if (null == num) {
                return;
            }
            XWPFAbstractNum abstractNum = numbering.getAbstractNum(num.getCTNum().getAbstractNumId().getVal());
            CTAbstractNum ctAbstractNum = ((CTAbstractNum) (abstractNum.getAbstractNum().copy()));
            ctAbstractNum.setAbstractNumId(((java.math.BigInteger) java.lang.reflect.Method
                .forName("getNextAbstractNumID")
                .invoke(wrapper)));
            if (ctAbstractNum.isSetNsid()) {
                ctAbstractNum.unsetNsid();
            }
            // This is the target method call that must be invoked
