package com.deepoove.poi.render.processor;

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFNumbering;
import org.apache.poi.xwpf.usermodel.XWPFNum;
import org.apache.poi.xwpf.usermodel.XWPFAbstractNum;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTAbstractNum;
import com.deepoove.poi.xwpf.XWPFNumberingWrapper;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigInteger;
import java.util.HashMap;

public class NumberingContinueupdateNumbering_CTAbstractNumunsetNsidFikaTest {

    @Test
    public void testUpdateNumberingInvokesUnsetNsid() throws Exception {
        // Create real document and numbering
        XWPFDocument document = new XWPFDocument();
        XWPFNumbering numbering = document.createNumbering();

        // Create source paragraph with numbering
        XWPFParagraph source = document.createParagraph();
        source.setNumID(BigInteger.ONE);

        // Create target paragraph
        XWPFParagraph target = document.createParagraph();

        // Create abstract num with nsid set
        CTAbstractNum ctAbstractNum = CTAbstractNum.Factory.newInstance();
        ctAbstractNum.setAbstractNumId(BigInteger.ONE);
        ctAbstractNum.setNsid(ctAbstractNum.addNewNsid());

        // Create XWPFAbstractNum wrapper
        XWPFAbstractNum abstractNum = new XWPFAbstractNum(ctAbstractNum);

        // Mock numbering to return required objects
        XWPFNum mockNum = Mockito.mock(XWPFNum.class);
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTNum mockCTNum = 
            org.openxmlformats.schemas.wordprocessingml.x2006.main.CTNum.Factory.newInstance();
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTDecimalNumber mockAbstractNumId = 
            org.openxmlformats.schemas.wordprocessingml.x2006.main.CTDecimalNumber.Factory.newInstance();

        mockAbstractNumId.setVal(BigInteger.ONE);
        mockCTNum.setAbstractNumId(mockAbstractNumId);
        Mockito.when(mockNum.getCTNum()).thenReturn(mockCTNum);
        Mockito.when(numbering.getNum(BigInteger.ONE)).thenReturn(mockNum);
