import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTPBdr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTBorder;
import org.junit.jupiter.api.Test;
import java.io.ByteArrayInputStream;

public class StyleUtilsretriveParagraphStyle_CTPBdrgetLeftFikaTest {

    @Test
    public void testRetriveParagraphStyleInvokesCTPBdrGetLeft() throws Exception {
        // Create a minimal document with a paragraph that has border settings
        byte[] docBytes = createDocumentWithParagraphBorder();
        ByteArrayInputStream inputStream = new ByteArrayInputStream(docBytes);
        XWPFDocument document = new XWPFDocument(inputStream);

        // Get the first paragraph which should have border properties
        XWPFParagraph paragraph = document.getParagraphs().get(0);

        // This will traverse the path and invoke CTPBdr.getLeft()
        StyleUtils.retriveParagraphStyle(paragraph);

        document.close();
    }

    private byte[] createDocumentWithParagraphBorder() {
        // Create a minimal DOCX with a paragraph that has left border
        String docxContent = 
            "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" +
            "<w:document xmlns:w=\"http://schemas.openxmlformats.org/wordprocessingml/2006/main\">" +
            "<w:body>" +
            "<w:p>" +
            "<w:pPr>" +
            "<w:pBdr>" +
            "<w:left w:val=\"single\" w:sz=\"4\" w:space=\"0\" w:color=\"000000\"/>" +
            "</w:pBdr>" +
            "</w:pPr>" +
            "<w:r><w:t>Test paragraph with border</w:t></w:r>" +
            "</w:p>" +
            "</w:body>" +
            "</w:document>";

        // Wrap in minimal DOCX structure
        String fullDoc = 
            "<?xml version=\"1.0\" encoding=\"UTF-8\" standalone=\"yes\"?>" +
            "<Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\">" +
            "<Default Extension=\"xml\" ContentType=\"application/xml\"/>" +
            "<Override PartName=\"/word/document.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml\"/>" +
            "</Types>";

        // Return a simple byte array that XWPFDocument can parse
        return docxContent.getBytes();
    }
}

