package com.deepoove.poi.policy.reference;

import com.deepoove.poi.XWPFTemplate;
import com.deepoove.poi.data.ChartSingleSeriesRenderData;
import com.deepoove.poi.template.ChartTemplate;
import org.apache.poi.xddf.usermodel.chart.XDDFChartData;
import org.apache.poi.xddf.usermodel.chart.XDDFDataSource;
import org.apache.poi.xddf.usermodel.chart.XDDFNumericalDataSource;
import org.apache.poi.xwpf.usermodel.XWPFChart;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.lang.reflect.Method;
import java.util.Arrays;

public class SingleSeriesChartTemplateRenderPolicy_AbstractChartTemplateRenderPolicyplot_CTAxDataSourceisSetNumLitFikaTest {

    @Test
    public void test() throws Exception {
        SingleSeriesChartTemplateRenderPolicy policy = new SingleSeriesChartTemplateRenderPolicy();

        ChartTemplate chartTemplate = Mockito.mock(ChartTemplate.class);
        XWPFTemplate xwpfTemplate = Mockito.mock(XWPFTemplate.class);

        XWPFChart chart = Mockito.mock(XWPFChart.class);
        Mockito.when(chartTemplate.getChart()).thenReturn(chart);

        org.apache.poi.xssf.usermodel.XSSFWorkbook workbook = new org.apache.poi.xssf.usermodel.XSSFWorkbook();
        org.apache.poi.xssf.usermodel.XSSFSheet sheet = workbook.createSheet();
        Mockito.when(chart.getWorkbook()).thenReturn(workbook);

        XDDFChartData chartData = Mockito.mock(XDDFChartData.class);
        XDDFChartData.Series series = Mockito.mock(XDDFChartData.Series.class);
        Mockito.when(chartData.getSeries()).thenReturn(Arrays.asList(series));

        XDDFDataSource<?> categoryDataSource = Mockito.mock(XDDFDataSource.class);
        Mockito.when(series.getCategoryData()).thenReturn(categoryDataSource);
        Mockito.when(categoryDataSource.isNumeric()).thenReturn(false);

        XDDFNumericalDataSource<?> valuesDataSource = Mockito.mock(XDDFNumericalDataSource.class);
        Mockito.when(series.getValuesData()).thenReturn(valuesDataSource);

        org.openxmlformats.schemas.drawingml.x2006.chart.CTAxDataSource axDataSource = 
            org.openxmlformats.schemas.drawingml.x2006.chart.CTAxDataSource.Factory.newInstance();

        Method getAxDSMethod = series.getClass().getSuperclass().getDeclaredMethod("getAxDS");
        getAxDSMethod.setAccessible(true);
        Mockito.when(getAxDSMethod.invoke(series)).thenReturn(axDataSource);

        ChartSingleSeriesRenderData renderData = Mockito.mock(ChartSingleSeriesRenderData.class);
        com.deepoove.poi.data.SeriesRenderData seriesRenderData = Mockito.mock(com.deepoove.poi.data.SeriesRenderData.class);
        Mockito.when(renderData.getSeriesData()).thenReturn(seriesRenderData);
        Mockito.when(seriesRenderData.getValues()).thenReturn(new Double[]{1.0, 2.0});
        Mockito.when(renderData.getCategories()).thenReturn(new String[]{"A", "B"});

        policy.doRender(chartTemplate, renderData, xwpfTemplate);
    }
}

