import org.apache.poi.xwpf.usermodel.IBodyElement;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.ArrayList;
import java.util.List;

public class NiceXWPFDocumentgetBodyElementSpecificPos_IBodyElementgetElementTypeFikaTest {

    @Test
    public void testRemoveBodyElementTriggersGetElementType() throws Exception {
        XWPFDocument mockDocument = Mockito.mock(XWPFDocument.class);
        org.apache.poi.xwpf.usermodel.XWPFBody mockBody = Mockito.mock(org.apache.poi.xwpf.usermodel.XWPFBody.class);
        Mockito.when(mockDocument.getBody()).thenReturn(mockBody);

        NiceXWPFDocument document = new NiceXWPFDocument(mockDocument);

        List<IBodyElement> bodyElements = new ArrayList<>();
        IBodyElement mockContentControl = Mockito.mock(IBodyElement.class);
        Mockito.when(mockContentControl.getElementType()).thenReturn(IBodyElement.BodyElementType.CONTENTCONTROL);
        bodyElements.add(mockContentControl);

        List<IBodyElement> contentControls = new ArrayList<>();
        contentControls.add(mockContentControl);

        document.setBodyElements(bodyElements);
        document.setContentControls(contentControls);

        document.removeBodyElement(0);
    }
}

