    cursor.dispose();
}

public XWPFStructuredDocumentTagContent(CTSdtContentBlock block, IBody part, XWPFStructuredDocumentTag parent) {
    this.sdtContentBlock = block;
    this.sdt = parent;
    if (block == null) {
        return;
    }
    XmlCursor cursor = block.newCursor();
    cursor.selectPath("./*");
    while (cursor.toNextSelection()) {
        XmlObject o = cursor.getObject();
        if (o instanceof CTP) {
            XWPFParagraph p = new XWPFParagraph(((CTP) (o)), this);
            paragraphs.add(p);
            sdtElements.add(p);
        } else if (o instanceof CTTbl) {
            XWPFTable t = new XWPFTable(((CTTbl) (o)), this);
            sdtElements.add(t);
        } else if (o instanceof CTSdtBlock) {
            XWPFStructuredDocumentTag c = new XWPFStructuredDocumentTag(((CTSdtBlock) (o)), this);
            sdtElements.add(c);
        } else if (o instanceof CTR) {
            XWPFRun run = new XWPFRun(((CTR) (o)), this);
            // runs.add(run);
            sdtElements.add(run);
        }
    } 
    cursor.dispose();
}

public XWPFStructuredDocumentTagContent(CTSdtContentCell cell, XWPFTableRow row, IBody part, XWPFStructuredDocumentTag parent) {
    this.sdt = parent;
    this.sdtContentCell = cell;
