    @Test
    public void test() throws Exception {
        // Create mock RunBodyContext
        RunBodyContext mockContext = Mockito.mock(RunBodyContext.class);

        // Create a real XWPFRun that will be returned by insertNewRunAfter
        XWPFRun realRun = Mockito.mock(XWPFRun.class);

        // Create a list of runs with at least one element
        List<XWPFRun> runs = new ArrayList<>();
        XWPFRun existingRun = Mockito.mock(XWPFRun.class);
        runs.add(existingRun);

        // Mock the CTR to have tab elements
        org.apache.poi.xwpf.usermodel.XWPFRun.CTR ctr = Mockito.mock(org.apache.poi.xwpf.usermodel.XWPFRun.CTR.class);
        Mockito.when(existingRun.getCTR()).thenReturn(ctr);

        // Make sure sizeOfTabArray returns > 0 to enter the if block
        Mockito.when(ctr.sizeOfBrArray()).thenReturn(0);
        Mockito.when(ctr.sizeOfCrArray()).thenReturn(0);
        Mockito.when(ctr.sizeOfTabArray()).thenReturn(1);

        // Mock the store and find_all_element_users to return a CTEmpty with tab tag
        org.apache.xmlbeans.impl.store.Cur.Cur ctrimpl = Mockito.mock(org.apache.xmlbeans.impl.store.Cur.Cur.class);
        Mockito.when(ctr.get_store()).thenReturn(ctrimpl);

        List<Object> xmlObjects = new ArrayList<>();
        org.apache.poi.xwpf.usermodel.CTEmpty ctEmpty = Mockito.mock(org.apache.poi.xwpf.usermodel.CTEmpty.class);
        org.w3c.dom.Node domNode = Mockito.mock(org.w3c.dom.Node.class);
        Mockito.when(ctEmpty.getDomNode()).thenReturn(domNode);
        Mockito.when(domNode.getNodeName()).thenReturn("w:tab");
        xmlObjects.add(ctEmpty);

        Mockito.when(ctrimpl.find_all_element_users(Mockito.any(), Mockito.any())).thenAnswer(invocation -> {
            List<?> list = invocation.getArgument(1);
            list.addAll(xmlObjects);
            return null;
        });

        // Setup mock context behavior
        Mockito.when(mockContext.getRuns()).thenReturn(runs);
        Mockito.when(mockContext.insertNewRunAfter(Mockito.anyInt())).thenReturn(realRun);

        // Create pattern that will match
        Pattern pattern = Pattern.compile(".*");

        // Create the object - this will trigger the constructor and potentially refactorBody
        RunningRunBody runningRunBody = new RunningRunBody(mockContext, pattern);
    }
}

