public class HelperapplyMergeRule_CTRowsizeOfTcArrayFikaTest {

    @Test
    public void testRenderTablePathToSizeOfTcArray() throws Exception {
        // Create a real XWPFRun from a real document
        XWPFDocument document = new XWPFDocument();
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun run = paragraph.createRun();

        // Create minimal TableRenderData with merge rule
        List<RowRenderData> rows = new ArrayList<>();
        rows.add(RowRenderData.build("Cell1", "Cell2"));
        rows.add(RowRenderData.build("Cell3", "Cell4"));

        MergeCellRule mergeRule = MergeCellRule.builder()
                .map(new Grid(0, 0), new Grid(0, 1))
                .build();

        TableRenderData data = new TableRenderData(rows);
        data.setMergeRule(mergeRule);
        data.setTableStyle(new TableStyle());

        // Invoke the entry point method
        TableRenderPolicy.Helper.renderTable(run, data);

        // Clean up
        document.close();
    }

    // Helper class to make Grid available
    private static class Grid {
        private final int i;
        private final int j;

        public Grid(int i, int j) {
            this.i = i;
            this.j = j;
        }

        public int getI() { return i; }
        public int getJ() { return j; }
    }
}

