        // 2. StyleUtils.styleParaRpr(CTParaRPr, Style)
        // 3. CTParaRPr.getUArray(0) when underline pattern is set
        StyleUtils.styleParaRpr(paragraph, style);

        // Clean up
        document.close();
    }
}

