package com.deepoove.poi.util;

import org.junit.jupiter.api.Test;
import com.deepoove.poi.data.style.Style;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import com.deepoove.poi.data.style.UnderlinePatterns;
import java.math.BigDecimal;

public class StyleUtilsstyleParaRpr_CTUnderlinesetColorFikaTest {

    @Test
    public void testStyleParaRprToCTUnderlineSetColor() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFParagraph paragraph = document.createParagraph();

        Style style = new Style();
        style.setUnderlinePatterns(UnderlinePatterns.SINGLE);
        style.setUnderlineColor("FF0000");
        style.setColor("000000");
        style.setItalic(true);
        style.setBold(true);
        style.setFontSize(12);
        style.setStrike(true);
        style.setFontFamily("Arial");
        style.setWesternFontFamily("Times New Roman");

        StyleUtils.styleParaRpr(paragraph, style);

        document.close();
    }
}

