@ExtendWith(MockitoExtension.class)
public class XmlXWPFDocumentMergemergeStyles_POIXMLUnitsparseOnOffFikaTest {

    @Mock
    private NiceXWPFDocument mockSourceDocument;

    @Mock
    private NiceXWPFDocument mockMergeDocument;

    @Mock
    private Iterator<NiceXWPFDocument> mockIterator;

    @Mock
    private XWPFRun mockRun;

    @Mock
    private XWPFParagraph mockParagraph;

    @Mock
    private XWPFStyles mockStyles;

    @Mock
    private XWPFStyles mockMergeStyles;

    @Mock
    private XWPFStyle mockStyle;

    @Mock
    private CTBody mockBody;

    @Mock
    private CTP mockCTP;

    @Test
    public void testMergeChain() throws Exception {
        XmlXWPFDocumentMerge merger = new XmlXWPFDocumentMerge();

        // Setup mock behavior to reach the target method
        org.mockito.Mockito.when(mockSourceDocument.getDocument()).thenReturn(new org.apache.poi.xwpf.usermodel.XWPFDocument() {
            @Override
            public CTBody getBody() {
                return mockBody;
            }
        });

        org.mockito.Mockito.when(mockIterator.hasNext()).thenReturn(true, false);
        org.mockito.Mockito.when(mockIterator.next()).thenReturn(mockMergeDocument);

        org.mockito.Mockito.when(mockRun.getParent()).thenReturn(mockParagraph);
        org.mockito.Mockito.when(mockParagraph.getCTP()).thenReturn(mockCTP);

        org.mockito.Mockito.when(mockSourceDocument.getStyles()).thenReturn(mockStyles);
        org.mockito.Mockito.when(mockMergeDocument.getStyles()).thenReturn(mockMergeStyles);

        // Create a real CTStyle with isSetDefault=true and xgetDefault returning STOnOff
        CTStyle ctStyle = CTStyle.Factory.newInstance();
        ctStyle.setDefault(STOnOff.Factory.newInstance());
        ctStyle.setStyleId("TestStyle");
        ctStyle.setType(STStyleType.PARAGRAPH);

        // Create a list containing one XWPFStyle with the CTStyle
        List<XWPFStyle> styleList = new ArrayList<>();
        org.apache.poi.xwpf.usermodel.XWPFStyle realStyle = new org.apache.poi.xwpf.usermodel.XWPFStyle(ctStyle, null);
        styleList.add(realStyle);

        // Use reflection to set the listStyle field
        try {
            java.lang.reflect.Field listStyleField = XWPFStyles.class.getDeclaredField("listStyle");
            listStyleField.setAccessible(true);
            listStyleField.set(mockMergeStyles, styleList);
        } catch (Exception e) {
            // Fallback if reflection fails
        }

        // Execute the entry point method
        merger.merge(mockSourceDocument, mockIterator, mockRun);
    }
}

