        // Create merged document with numbering
        NiceXWPFDocument mergedDoc = new NiceXWPFDocument();
        XWPFNumbering mergedNumbering = mergedDoc.createNumbering();

        // Create an abstract num in merged document
        CTAbstractNum ctAbstractNum = CTAbstractNum.Factory.newInstance();
